<?php
ob_start();require 'C:/xampp/htdocs/boticav1/config/database.php';$db=appPdoConnection();session_id('receiptpreview'.bin2hex(random_bytes(6)));session_start();$_SESSION=array('user'=>'superadmin','idPerfil'=>1,'idAlmacen'=>1,'hostUrl'=>'http://localhost/','HostUrl'=>'http://localhost/','expire'=>time()+90,'permisos'=>array());$sid=session_id();session_write_close();
$rows=$db->query("SELECT MIN(v.IdDocVenta) id,t.CodSunat FROM Ve_DocVenta v JOIN Ve_DocVentaTipoDoc t ON t.IdTipoDoc=v.IdTipoDoc WHERE t.CodSunat IN ('01','03') GROUP BY t.CodSunat")->fetchAll(PDO::FETCH_ASSOC);$failed=false;
foreach($rows as $row){$ch=curl_init('http://localhost/imprimir/index.php?IdDocVenta='.(int)$row['id'].'&preview=1');curl_setopt_array($ch,array(CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIE=>session_name().'='.$sid,CURLOPT_TIMEOUT=>20));$html=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$ok=$status===200&&strpos($html,'class="ticket"')!==false&&strpos($html,'data:image/png;base64,')!==false&&strpos($html,'Fatal error')===false&&strpos($html,'Warning:')===false;if(!$ok)$failed=true;echo ($ok?'PASS':'FAIL').' Receipt '.$row['CodSunat'].' live preview HTTP '.$status."\n";}
session_id($sid);session_start();$_SESSION=array();session_destroy();ob_end_flush();exit($failed?1:0);
